            letterSpacing: '0.2em',
            textTransform: 'uppercase',
            color: theme.foreground,
            textShadow: labelShadow(theme.background),
            opacity: brandIn,
            transform: `translateY(${(1 - brandIn) * -16}px)`,
            whiteSpace: 'nowrap',
          }}
        >
          <Role role="brand">{texts.brand}</Role>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
